<template>
	<div class="space-y-4">
		<div class="flex items-center justify-between gap-3"><div><h3 class="font-semibold">Customer Display Content</h3><p class="text-xs text-muted-foreground">Arrange content by dragging it into playlist order.</p></div><Button size="sm" @click="beginAdd">+ Add Content</Button></div>
		<div v-if="formOpen" class="rounded-lg border border-border p-4 space-y-3">
			<h4 class="font-medium">{{ editingId ? "Edit content" : "Add content" }}</h4>
			<div class="grid gap-3 md:grid-cols-2"><label>Title<Input v-model="draft.title" placeholder="Weekend promotion" @keydown.stop /></label><label>Content type<select v-model="draft.type"><option value="video">Video</option><option value="image">Image</option><option value="html">HTML</option></select></label></div>
			<div v-if="draft.type !== 'html'" class="space-y-2"><label>Media source</label><div class="flex gap-4 text-sm"><label><input v-model="source" type="radio" value="upload" /> Upload file</label><label><input v-model="source" type="radio" value="url" /> External URL</label><span v-if="draft.file" class="text-xs" :class="statusClass(draft.file)">● {{ statusLabel(draft.file) }}</span></div><div v-if="source === 'upload'" class="flex items-center gap-3"><input id="advertisement-file" class="sr-only" type="file" :accept="draft.type === 'video' ? 'video/*' : 'image/*'" @change="uploadFile" /><label for="advertisement-file" class="file-button">Choose {{ draft.type }} file</label><span class="text-sm text-muted-foreground">{{ selectedFileName || 'No file selected' }}</span></div><Input v-else v-model="draft.file" placeholder="https://…" @keydown.stop /></div>
			<label v-else>HTML content<textarea v-model="draft.content" rows="6" placeholder="&lt;p&gt;Weekend Sale&lt;/p&gt;" @keydown.stop /></label>
			<div class="grid gap-3 md:grid-cols-3"><label>Show for (seconds)<Input v-model.number="draft.duration" min="3" max="3600" type="number" /></label><label>Display mode<select v-model="draft.fit"><option value="cover">Cover (Fill screen)</option><option value="contain">Contain (Show full content)</option><option value="fill">Stretch</option></select></label><label>Availability<select v-model="availability"><option value="always">Always active</option><option value="scheduled">Scheduled</option><option value="disabled">Disabled</option></select></label></div>
			<div v-if="availability === 'scheduled'" class="rounded-md bg-muted p-3 space-y-2"><div class="grid gap-3 md:grid-cols-2"><label>Start date and time<Input v-model="draft.startDate" type="datetime-local" /></label><label>End date and time<Input v-model="draft.endDate" type="datetime-local" /></label></div><p class="text-xs text-muted-foreground">Content is active only within this schedule.</p></div>
			<label v-if="draft.type === 'video'" class="flex gap-2 text-sm"><Checkbox v-model:checked="draft.loop" /> Loop video during its display time</label><div class="flex gap-2"><Button :disabled="uploading" @click="save">{{ editingId ? 'Save content' : 'Add content' }}</Button><Button variant="outline" @click="closeForm">Cancel</Button><span v-if="uploading" class="text-sm text-muted-foreground">Uploading…</span></div>
		</div>
		<div v-if="playlist.length" class="space-y-2"><h4 class="font-medium">Playlist</h4><div v-for="(ad, index) in orderedPlaylist" :key="ad.id" draggable="true" class="content-card" :class="{ dragging: draggedId === ad.id, 'drop-target': dropTargetId === ad.id && draggedId !== ad.id }" @dragstart="startDrag($event, ad.id)" @dragend="clearDrag" @dragover.prevent="dropTargetId = ad.id" @dragleave="dropTargetId = ''" @drop="drop($event, ad.id)"><div class="flex min-w-0 gap-3"><span class="drag-handle" aria-label="Drag to reorder">☰</span><div><p class="font-medium">{{ ad.title }} <span v-if="ad.type !== 'html'" class="text-xs" :class="statusClass(ad.file)">● {{ statusLabel(ad.file) }}</span></p><div class="mt-1 grid gap-x-4 gap-y-1 text-xs text-muted-foreground sm:grid-cols-2"><span>{{ typeLabel(ad.type) }}</span><span>Duration: {{ ad.duration }} seconds</span><span>Position: {{ index + 1 }}</span><span>Mode: {{ modeLabel(ad.fit) }}</span><span>Availability: {{ availabilityLabel(ad) }}</span><span>Schedule: {{ scheduleLabel(ad) }}</span></div></div></div><div class="flex shrink-0 gap-1"><Button size="sm" variant="outline" :disabled="index === 0" @click="move(ad.id, -1)">↑</Button><Button size="sm" variant="outline" :disabled="index === orderedPlaylist.length - 1" @click="move(ad.id, 1)">↓</Button><Button size="sm" variant="outline" @click="preview(ad)">Preview</Button><Button size="sm" variant="outline" @click="edit(ad)">Edit</Button><Button size="sm" variant="destructive" @click="remove(ad.id)">Delete</Button></div></div></div>
	</div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { toast } from "vue-sonner";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { type Advertisement, isAdvertisementActive, saveAdvertisementPlaylist, useAdvertisementPlaylist } from "@/composables/useAdvertisementPlaylist";
import { checkCustomerDisplayMedia, type CustomerDisplayAssetCheck } from "@/services/customerDisplayStorage";
const { playlist } = useAdvertisementPlaylist();
const source = ref<"upload" | "url">("upload"), uploading = ref(false), editingId = ref(""), selectedFileName = ref(""), availability = ref<"always" | "scheduled" | "disabled">("always"), formOpen = ref(false), draggedId = ref(""), dropTargetId = ref("");
const currentTime = ref(new Date()); let statusTimer: number | undefined;
const mediaChecks = ref<CustomerDisplayAssetCheck[]>([]);
onMounted(() => { statusTimer = window.setInterval(() => { currentTime.value = new Date(); }, 1000); void refreshMediaChecks(); });
watch(playlist, () => { void refreshMediaChecks(); }, { deep: true });
onBeforeUnmount(() => { if (statusTimer) window.clearInterval(statusTimer); });
const orderedPlaylist = computed(() => [...playlist.value].sort((a, b) => a.order - b.order));
const empty = (): Advertisement => ({ id: crypto.randomUUID(), title: "", type: "video", file: "", duration: 15, order: playlist.value.length + 1, enabled: true, loop: true, fit: "cover", content: "" }); const draft = ref<Advertisement>(empty());
watch(() => draft.value.file, async (url) => { if (!url) return; const checks = await checkCustomerDisplayMedia([url]).catch(() => []); mediaChecks.value = [...mediaChecks.value.filter((check) => check.url !== url), ...checks]; });
function reset() { editingId.value = ""; source.value = "upload"; selectedFileName.value = ""; availability.value = "always"; draft.value = empty(); }
function beginAdd() { reset(); formOpen.value = true; }
function closeForm() { reset(); formOpen.value = false; }
function persist(ordered = playlist.value) { const normalized = ordered.map((ad, index) => ({ ...ad, order: index + 1 })); playlist.value.splice(0, playlist.value.length, ...normalized); saveAdvertisementPlaylist(normalized); }
function save() { if (!draft.value.title.trim()) return toast.error("Content title is required"); if (draft.value.type === "html" ? !draft.value.content?.trim() : !draft.value.file.trim()) return toast.error("Add HTML or a media file/URL first"); draft.value.enabled = availability.value !== "disabled"; if (availability.value !== "scheduled") { draft.value.startDate = ""; draft.value.endDate = ""; } if (draft.value.endDate && draft.value.startDate && draft.value.endDate < draft.value.startDate) return toast.error("End date must be after the start date"); const index = playlist.value.findIndex((ad) => ad.id === editingId.value); if (index >= 0) playlist.value.splice(index, 1, { ...draft.value }); else playlist.value.push({ ...draft.value }); persist(orderedPlaylist.value); toast.success("Content saved"); closeForm(); }
function edit(ad: Advertisement) { editingId.value = ad.id; draft.value = { fit: "cover", ...ad }; availability.value = !ad.enabled ? "disabled" : (ad.startDate || ad.endDate ? "scheduled" : "always"); source.value = ad.file.startsWith("/") ? "upload" : "url"; selectedFileName.value = ad.file.split("/").pop() || ""; formOpen.value = true; }
function remove(id: string) { const index = playlist.value.findIndex((ad) => ad.id === id); if (index >= 0) { playlist.value.splice(index, 1); persist(orderedPlaylist.value); } }
function startDrag(event: DragEvent, id: string) { draggedId.value = id; event.dataTransfer?.setData("text/plain", id); if (event.dataTransfer) { event.dataTransfer.effectAllowed = "move"; event.dataTransfer.dropEffect = "move"; } }
function clearDrag() { draggedId.value = ""; dropTargetId.value = ""; }
function move(id: string, direction: -1 | 1) { const from = orderedPlaylist.value.findIndex((ad) => ad.id === id); const to = from + direction; if (from < 0 || to < 0 || to >= orderedPlaylist.value.length) return; const reordered = [...orderedPlaylist.value], [moved] = reordered.splice(from, 1); reordered.splice(to, 0, moved); persist(reordered); }
function drop(event: DragEvent, targetId: string) { event.preventDefault(); const sourceId = event.dataTransfer?.getData("text/plain") || draggedId.value; const from = orderedPlaylist.value.findIndex((ad) => ad.id === sourceId), to = orderedPlaylist.value.findIndex((ad) => ad.id === targetId); if (from >= 0 && to >= 0 && from !== to) { const reordered = [...orderedPlaylist.value], [moved] = reordered.splice(from, 1); reordered.splice(to, 0, moved); persist(reordered); } clearDrag(); }
function preview(ad: Advertisement) { const popup = window.open(`${window.location.origin}/xpos/customer-display?preview=${encodeURIComponent(ad.id)}`, "xpos-customer-display-preview", "popup=yes,width=1024,height=768"); if (!popup) toast.error("Popup was blocked. Allow popups for this site, then try again."); else popup.focus(); }
function typeLabel(type: Advertisement["type"]) { return type === "html" ? "▣ HTML" : type === "video" ? "🎥 Video" : "▧ Image"; } function modeLabel(fit?: Advertisement["fit"]) { return fit === "cover" ? "Cover" : fit === "fill" ? "Stretch" : "Contain"; } function availabilityLabel(ad: Advertisement) { return ad.enabled ? "Enabled" : "Disabled"; } function scheduleLabel(ad: Advertisement) { if (!ad.enabled) return "Not scheduled"; return ad.startDate || ad.endDate ? (isAdvertisementActive(ad, currentTime.value) ? "Active" : "Inactive") : "Always active"; }
function statusLabel(url: string) { const status = mediaChecks.value.find((item) => item.url === url)?.status; return status === "available" ? "Available" : status === "missing" ? "Missing" : status === "unavailable" ? "URL unavailable" : "Checking…"; } function statusClass(url: string) { const status = mediaChecks.value.find((item) => item.url === url)?.status; return status === "available" ? "text-emerald-600" : ["missing", "unavailable"].includes(status || "") ? "text-destructive" : "text-muted-foreground"; } async function refreshMediaChecks() { const urls = [...new Set(playlist.value.filter((ad) => ad.type !== "html" && ad.file).map((ad) => ad.file))]; mediaChecks.value = urls.length ? await checkCustomerDisplayMedia(urls).catch(() => []) : []; }
async function uploadFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; selectedFileName.value = file.name; uploading.value = true; try { const form = new FormData(); form.append("file", file); form.append("is_private", "0"); const csrf = window.xpos?.csrf_token || (document.querySelector('meta[name="csrf-token"]') as HTMLMetaElement | null)?.content || ""; const response = await fetch("/api/method/upload_file", { method: "POST", body: form, credentials: "same-origin", headers: csrf ? { "X-Frappe-CSRF-Token": csrf } : {} }), data = await response.json(); if (!response.ok || !data.message?.file_url) throw new Error(); draft.value.file = data.message.file_url; toast.success("Media uploaded"); } catch { toast.error("Upload failed. Check Frappe File permission or use a URL."); } finally { uploading.value = false; } }
</script>
<style scoped>label{display:grid;gap:.35rem;font-size:.875rem;font-weight:500}select,textarea{width:100%;border:1px solid hsl(var(--border));border-radius:.375rem;background:transparent;padding:.5rem;font:inherit}textarea{resize:vertical}.file-button{display:inline-flex!important;width:max-content;cursor:pointer;border:1px solid hsl(var(--border));border-radius:.375rem;padding:.5rem .75rem;background:hsl(var(--secondary));font-weight:600}.content-card{display:flex;align-items:center;justify-content:space-between;gap:.75rem;border:1px solid hsl(var(--border));border-radius:.5rem;padding:.75rem;cursor:grab}.content-card.dragging{opacity:.45}.content-card.drop-target{border-color:hsl(var(--primary));box-shadow:0 0 0 1px hsl(var(--primary))}.drag-handle{cursor:grab;font-size:1.25rem;color:hsl(var(--muted-foreground));line-height:1}</style>
